$$
P(i,2)= \sum_{i \neq x} (P_x . \frac {P_i}{(1 - P_x)  })
$$ 
 // Calc 2nd place for each horse
for (HorseData hdi : hdList) {
    for (HorseData hdx : hdList) {
        if (hdi.id != hdx.id) {
