$\ds{\int_{-1}^{1}{\dd z \over \root[3]{\pars{1 - z}\pars{1 + z}^{2}}}
     =\color{#c00000}{\int_{0}^{2}z^{-2/3}\pars{2 - z}^{-1/3}\,\dd z}:\
     {\large ?}}$ 

 \begin{align}&\int_{2}^{0}\!\!z^{-2/3}\expo{\pars{-2/3}0\ic}
\pars{2 - z}^{-1/3}\expo{\pars{-1/3}2\pi\ic}\,\dd z
+\int_{0}^{2}\!z^{-2/3}\expo{\pars{-2/3}0\ic}
\pars{2 - z}^{-1/3}\expo{\pars{-1/3}0\ic}\,\dd z
\\[3mm]&=\pars{-\expo{-2\pi\ic/3} + 1}
\color{#c00000}{\int_{0}^{2}z^{-2/3}\pars{2 - z}^{-1/3}\,\dd z}
=-2\pi\ic\,{\rm Res}_{z\ =\ 0}\bracks{%
-\,{1 \over z^{2}}\,z^{2/3}\pars{2 - {1 \over z}}^{-1/3}}
\\[3mm]&=2\pi\ic\,{\rm Res}_{z\ =\ 0}\bracks{{\pars{2z - 1}^{-1/3} \over z}}
=2\pi\ic\,{\rm Res}_{z\ =\ 0}
\bracks{{\verts{2z - 1}^{-1/3}\expo{\pars{-1/3}\pi\ic} \over z}}
=2\pi\ic\expo{-\pi\ic/3}
\end{align} 

 \begin{align}
&\color{#00f}{\large%
\int_{-1}^{1}{\dd z \over \root[3]{\pars{1 - z}\pars{1 + z}^{2}}}}
=\color{#c00000}{\int_{0}^{2}z^{-2/3}\pars{2 - z}^{-1/3}\,\dd z}
={2\pi\ic\expo{-\pi\ic/3} \over -\expo{-2\pi\ic/3} + 1}
\\[3mm]&=\pi\,{2\ic \over \expo{\pi\ic/3} - \expo{-\pi\ic/3}}
={\pi \over \sin\pars{\pi/3}} = {\pi \over \root{3}/2}
